import unittest
from candidate import max_element

class TestMaxElement(unittest.TestCase):
    def test_max_element_in_list_of_positive_numbers(self):
        self.assertEqual(max_element([1, 2, 3]), 3)

    def test_max_element_in_list_of_mixed_numbers(self):
        self.assertEqual(max_element([5, 3, -5, 2, -3, 3, 9, 0, 123, 1, -10]), 123)

    def test_max_element_in_list_of_single_element(self):
        self.assertEqual(max_element([10]), 10)

    def test_max_element_in_empty_list(self):
        with self.assertRaises(IndexError):
            max_element([])

    def test_max_element_in_list_of_none(self):
        with self.assertRaises(TypeError):
            max_element([None])

    def test_max_element_in_list_of_non_numeric_values(self):
        with self.assertRaises(TypeError):
            max_element(['a', 'b', 'c'])

    def test_max_element_in_list_of_multiple_max_values(self):
        self.assertEqual(max_element([1, 2, 3, 3, 3, 3]), 3)

    def test_max_element_in_list_of_negative_numbers(self):
        self.assertEqual(max_element([-1, -2, -3]), -1)

if __name__ == '__main__':
    unittest.main()
